#include <bits/stdc++.h>
using namespace std;

const int MAXN = 20;
const int MAXNODES = 2020;
const int INF = 3010;

vector<int> graph[MAXNODES];
int level[MAXNODES];
int match[MAXNODES];
int dist_to_boundary[MAXN][MAXN], cell_capacity[MAXN][MAXN], enemy_cell[MAXN][MAXN];
char grid_s[MAXN][MAXN], grid_p[MAXN][MAXN];
int dd[MAXN][MAXN];
const int dx[4] = {0, 1, -1, 0};
const int dy[4] = {1, 0, 0, -1};
vector<int> source_pool[MAXN][MAXN], dest_pool[MAXN][MAXN];

void link(int a, int b) {
    graph[a].emplace_back(b);
    graph[b].emplace_back(a);
}

int src_count, dst_count;

bool build_level_graph() {
    queue<int> q;
    fill(level, level + src_count + 1, INF);
    for (int i = 1; i <= src_count; ++i) {
        if (match[i] == 0) {
            level[i] = 0;
            q.push(i);
        }
    }
    level[0] = INF;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (level[u] < level[0]) {
            for (int v_node : graph[u]) {
                int v = match[v_node];
                if (level[v] == INF) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }
    }
    return level[0] != INF;
}

bool dfs_path(int u) {
    if (u == 0) return true;
    for (int v_node : graph[u]) {
        int v = match[v_node];
        if (level[v] == level[u] + 1) {
            if (dfs_path(v)) {
                match[u] = v_node;
                match[v_node] = u;
                return true;
            }
        }
    }
    return false;
}

int compute_matching() {
    int result = 0;
    while (build_level_graph()) {
        for (int i = 1; i <= src_count; ++i) {
            if (match[i] == 0 && dfs_path(i)) {
                ++result;
            }
        }
    }
    return result;
}

int main() {
    int n, t;
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            dist_to_boundary[i][j] = t;
    for (int i = 1; i <= n; ++i)
        scanf("%s", grid_s[i] + 1);
    for (int i = 1; i <= n; ++i)
        scanf("%s", grid_p[i] + 1);
    int rx = 0, ry = 0;
    src_count = 1, dst_count = 1000;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid_s[i][j] == 'Z' || grid_s[i][j] == 'Y') {
                enemy_cell[i][j] = -1;
                dist_to_boundary[i][j] = 0;
            }
            if (grid_s[i][j] == 'Z') {
                rx = i; ry = j;
                dist_to_boundary[i][j] = 0;
            }
            if (isdigit(grid_s[i][j])) {
                enemy_cell[i][j] = grid_s[i][j] - '0';
                for (int k = 0; k < enemy_cell[i][j]; ++k)
                    source_pool[i][j].push_back(src_count++);
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (isdigit(grid_p[i][j])) {
                cell_capacity[i][j] = grid_p[i][j] - '0';
                for (int k = 0; k < cell_capacity[i][j]; ++k)
                    dest_pool[i][j].push_back(dst_count++);
            }
        }
    }
    queue<pair<int, int> > q;
    q.emplace(rx, ry);
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (dist_to_boundary[nx][ny] > dist_to_boundary[x][y] + 1 && enemy_cell[nx][ny] != -1) {
                dist_to_boundary[nx][ny] = dist_to_boundary[x][y] + 1;
                q.emplace(nx, ny);
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (enemy_cell[i][j] > 0) {
                for (int x = 1; x <= n; ++x)
                    for (int y = 1; y <= n; ++y)
                        dd[x][y] = 100000;
                queue<pair<int, int> > dq;
                dd[i][j] = 0;
                dq.emplace(i, j);
                while (!dq.empty()) {
                    int x = dq.front().first, y = dq.front().second;
                    dq.pop();
                    for (int src_id : source_pool[i][j]) {
                        for (int dst_id : dest_pool[x][y]) {
                            link(src_id, dst_id);
                        }
                    }
                    if (dd[x][y] == dist_to_boundary[x][y]) continue;
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (enemy_cell[nx][ny] != -1 && dd[nx][ny] > dd[x][y] + 1 && dd[x][y] + 1 <= dist_to_boundary[nx][ny]) {
                            dd[nx][ny] = dd[x][y] + 1;
                            dq.emplace(nx, ny);
                        }
                    }
                }
            }
        }
    }
    printf("%d", compute_matching());
    return 0;
}
